import{_ as r,c as t,o as l,aj as a}from"./chunks/framework.CDhdelVI.js";const g=JSON.parse('{"title":"Flour","description":"","frontmatter":{"title":"Flour"},"headers":[],"relativePath":"ingredients/flour.md","filePath":"ingredients/flour.md"}'),i={name:"ingredients/flour.md"};function o(n,e,s,d,h,u){return l(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="flour" tabindex="-1">Flour <a class="header-anchor" href="#flour" aria-label="Permalink to “Flour”">​</a></h1><p>Flour is the foundation of nearly every dough. Its protein content determines how much gluten can form, which affects structure, chew, and oven spring. Think of flour choice as a behavior dial: it changes how fast dough absorbs water, how strong it feels in shaping, and how open or tight the final crumb can be.</p><h2 id="types-of-flour" tabindex="-1">Types of Flour <a class="header-anchor" href="#types-of-flour" aria-label="Permalink to “Types of Flour”">​</a></h2><h3 id="bread-flour-high-protein" tabindex="-1"><strong>Bread Flour (High-Protein)</strong> <a class="header-anchor" href="#bread-flour-high-protein" aria-label="Permalink to “Bread Flour (High-Protein)”">​</a></h3><p>Most KitchenRatio recipes use <strong>bread flour</strong> because:</p><ul><li>Higher protein = stronger gluten network</li><li>Better rise and oven spring</li><li>Easier shaping</li><li>More tolerance to high hydration</li></ul><p>Typical protein content: <strong>12-13%</strong></p><h3 id="all-purpose-flour" tabindex="-1"><strong>All-Purpose Flour</strong> <a class="header-anchor" href="#all-purpose-flour" aria-label="Permalink to “All-Purpose Flour”">​</a></h3><ul><li>Lower protein (10-11%)</li><li>Softer crumb</li><li>Can be used for rolls or enriched doughs</li><li>May feel stickier at the same hydration</li></ul><h3 id="_00-flour" tabindex="-1"><strong>00 Flour</strong> <a class="header-anchor" href="#_00-flour" aria-label="Permalink to “00 Flour”">​</a></h3><ul><li>Very finely milled, usually lower to medium protein depending on brand</li><li>Great for pizza and tender crumb styles</li><li>Can feel softer and more extensible in mixing</li><li>Often benefits from a little less water than bread flour</li></ul><h3 id="rye-flour" tabindex="-1"><strong>Rye Flour</strong> <a class="header-anchor" href="#rye-flour" aria-label="Permalink to “Rye Flour”">​</a></h3><ul><li>Low gluten-forming potential, but very high water-binding behavior</li><li>Adds earthy flavor and deeper color</li><li>Can make dough feel tacky and dense if hydration is not adjusted</li><li>Works best in blends unless you are targeting a rye-forward style</li></ul><h3 id="whole-wheat-flour" tabindex="-1"><strong>Whole Wheat Flour</strong> <a class="header-anchor" href="#whole-wheat-flour" aria-label="Permalink to “Whole Wheat Flour”">​</a></h3><ul><li>Absorbs more water</li><li>Reduces extensibility</li><li>Adds flavor and fiber</li><li>Often blended 10-50% with white flour</li></ul><hr><h2 id="how-flour-affects-the-dough" tabindex="-1">How Flour Affects the Dough <a class="header-anchor" href="#how-flour-affects-the-dough" aria-label="Permalink to “How Flour Affects the Dough”">​</a></h2><ul><li><strong>Protein</strong> - Strength and chew</li><li><strong>Ash content</strong> - Flavor and fermentation behavior</li><li><strong>Hydration absorption</strong> - How sticky or stiff the dough feels</li></ul><p>High-protein bread flour is recommended for:</p><ul><li>Baguettes</li><li>Pizza dough</li><li>Hoagie rolls</li><li>Most lean doughs</li></ul><hr><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to “Tips”">​</a></h2><ul><li>Use the <strong>same brand</strong> of bread flour consistently for predictable hydration.</li><li>If switching flours, adjust hydration by <strong>±2-5%</strong>.</li><li>For softer rolls, blend <strong>80% bread flour + 20% AP</strong>.</li><li>00 flour usually needs slightly less water than bread flour in like-for-like swaps.</li><li>Rye can change dough behavior fast; when adding rye, watch adjusted effective hydration and dough feel, not just base hydration %.</li></ul><h2 id="quick-swap-guide" tabindex="-1">Quick Swap Guide <a class="header-anchor" href="#quick-swap-guide" aria-label="Permalink to “Quick Swap Guide”">​</a></h2><p>These are practical starting points when swapping from a bread-flour baseline. Brand, milling, and fermentation style can move these numbers.</p><table tabindex="0"><thead><tr><th>Flour Type</th><th>Typical Direction vs Bread Flour</th><th>Starting Hydration Change</th></tr></thead><tbody><tr><td>All-Purpose Flour</td><td>Slightly softer, slightly less thirsty</td><td>-1% to -2%</td></tr><tr><td>00 Flour</td><td>More extensible, often less thirsty</td><td>-1% to -3%</td></tr><tr><td>Whole Wheat Flour</td><td>Thirstier, tighter feel</td><td>+2% to +5%</td></tr><tr><td>Rye Flour</td><td>Much higher water-binding, denser feel if under-hydrated</td><td>+5% to +12%</td></tr></tbody></table><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/enrichment.html">Enrichment</a></li><li><a href="/recipes/colorado-pizza-dough.html">Colorado-Style Pizza Dough</a></li></ul>',28)])])}const c=r(i,[["render",o]]);export{g as __pageData,c as default};
